              style={{ ["--r" as string]: p0.r, opacity: p0.o }}
              animate={reduce ? undefined : { ["--r" as string]: R_KEYS, opacity: O_KEYS }}
              transition={{ duration: 8, ease: "linear", times: TIMES, repeat: Infinity, delay }}
            >
