        <div className="absolute left-0 top-[calc(501*var(--u))] w-[calc(314*var(--u))] text-center text-white text-[calc(13*var(--u))] leading-[calc(19*var(--u))] font-normal tracking-[calc(-0.15*var(--u))] antialiased">
