/* light colour first, dark colour second; --d flips 0 -> 1 */
const mix = (dark: string, light: string) => `color-mix(in srgb, ${dark} calc(var(--d) * 100%), ${light})`;
const VARS = {
  "--bg": mix("#000", "#f7f7f7"),
